"""Descriptive boundary audit; no semantic classifier or primary-data edits."""
import json,re,html,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[2];dest=R/'docs/data/base-behavior';dest.mkdir(parents=True,exist_ok=True)
manifest=json.load(open(R/'data/manifest.json'));records={r['id']:r for r in manifest['records']}
exact=json.load(open(R/'local/base-behavior/exact-inputs.json'))
pattern=re.compile(r'<\|(system|user|assistant)\|>')
def analyze(key,d):
 text=d['reply'];headers=list(pattern.finditer(text));first=text[:headers[0].start()].strip() if headers else text.strip();segments=[]
 for i,h in enumerate(headers):
  end=headers[i+1].start() if i+1<len(headers) else len(text)
  content=text[h.end():end].strip();complete=i+1<len(headers) or not d.get('reply_truncated',d.get('truncated',False))
  segments.append({'role':h.group(1),'text':content,'complete':complete,'repeats_supplied_user_text':h.group(1)=='user' and content in [records[key]['prompt'].strip(),records[key]['message'].strip()]})
 return {**exact['records'][key],'output_token_ids':d.get('token_ids',d.get('reply_token_ids',[])),'prefix_matches_original':d.get('prefix_matches_original'),'generated_tokens':d.get('tokens',len(d.get('reply_token_ids',[]))),'id':key,'task':records[key]['task'],'family':records[key]['family'],'prompt':records[key]['prompt'],'message':records[key]['message'],'reply':text,'first_segment':first,'first_segment_exact_copy':first==records[key]['message'].strip(),'full_exact_copy':text.strip()==records[key]['message'].strip(),'segments':segments,'truncated':d.get('reply_truncated',d.get('truncated',False)),'source_sha256':hashlib.sha256(json.dumps(d,sort_keys=True,ensure_ascii=False).encode()).hexdigest()}
short=[analyze(k,json.load(open(R/'local/llama-results-v2/llama-base/records'/(k+'.json')))) for k in records]
long=[]
for p in sorted((R/'local/base-behavior').glob('*-0.json')):
 d=json.load(open(p));long.append(analyze(d['id'],d))
summary={}
for task in ['assist','copy']:
 rs=[r for r in short if r['task']==task]
 summary[task]={'n':len(rs),'role_headers':sum(bool(r['segments']) for r in rs),'first_segment_exact_copy':sum(r['first_segment_exact_copy'] for r in rs),'full_exact_copy':sum(r['full_exact_copy'] for r in rs),'truncated':sum(r['truncated'] for r in rs),'complete_new_user_turn':sum(any(s['role']=='user' and s['complete'] and not s['repeats_supplied_user_text'] for s in r['segments']) for r in rs)}
for name,value in [('short-replies',short),('long-replies',long),('summary',summary)]:
 (dest/(name+'.json')).write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
e=html.escape
head=(R/'docs/index.html').read_text().split('<body>')[0].replace('<title>Assistant perspective · Qwen3.6</title>','<title>Base model · generated conversations</title>')
parts=[head, r'''<body>
<header><h1>Base behavior <span>· exact inputs and outputs</span></h1><a href="index.html?model=llama-base">Back to dashboard</a></header>
<main style="max-width:1100px">
<p>Choose an example to see the complete input actually fed into base Llama-3.1-70B, followed by everything it generated. Input text is decoded from the saved token IDs with special tokens retained; whitespace is preserved.</p>
<p class="hint">The input begins with the special token &lt;|begin_of_text|&gt;. The Tulu role headers &lt;|system|&gt;, &lt;|user|&gt; and &lt;|assistant|&gt; are literal text encoded as multiple tokens in this tokenizer. There is no &lt;|im_start|&gt; in these prompts.</p>
<div class="toolbar"><label>Run<select id="run"><option value="long">1,024-token continuations · 8 examples</option><option value="short">Original 256-token outputs · all 52 examples</option></select></label><label>Example<select id="example"></select></label></div>
<p id="metadata" class="meta"></p>
<h2>Full input</h2>
<pre id="input" class="raw" style="white-space:pre-wrap;overflow-wrap:anywhere"></pre>
<h2>Generated output</h2>
<p class="hint">Everything below was generated by the model, including any additional user, assistant or system headers. No turns have been split out or removed.</p>
<pre id="output" class="raw" style="white-space:pre-wrap;overflow-wrap:anywhere"></pre>
<details><summary>Exact input token IDs and token pieces</summary><pre id="tokens" class="raw" style="white-space:pre-wrap"></pre></details>
<p><a href="data/base-behavior/short-replies.json">Download all original inputs and outputs</a> · <a href="data/base-behavior/long-replies.json">Download longer inputs and outputs</a> · <a href="data/base-behavior/summary.json">Boundary audit counts</a></p>
</main>
<script>
const run=document.getElementById('run'),example=document.getElementById('example');
let datasets={};
function show(){const r=datasets[run.value].find(r=>r.id===example.value);if(!r)return;document.getElementById('input').textContent=r.input_text;document.getElementById('output').textContent=r.reply;document.getElementById('metadata').textContent=`${r.input_ids.length} input tokens · ${r.generated_tokens} generated tokens · ${r.truncated?'token cap reached':'stopped'}`;document.getElementById('tokens').textContent=r.input_ids.map((id,i)=>`${i}: ${id}  ${JSON.stringify(r.input_token_pieces[i])}`).join('\n');}
function selectRun(){const previous=example.value;example.replaceChildren(...datasets[run.value].map(r=>{const o=document.createElement('option');o.value=r.id;o.textContent=r.id;return o;}));if(datasets[run.value].some(r=>r.id===previous))example.value=previous;show();}
Promise.all(['long','short'].map(async name=>{const response=await fetch(`data/base-behavior/${name}-replies.json?v=exact-input-v1`);if(!response.ok)throw Error('Could not load examples');datasets[name]=await response.json();})).then(()=>{run.onchange=selectRun;example.onchange=show;selectRun();}).catch(e=>document.getElementById('metadata').textContent=e.message);
</script></body></html>''']
(R/'docs/base-behavior.html').write_text('\n'.join(parts))
print(json.dumps({'summary':summary,'long':len(long),'exact_inputs':len(exact['records'])}))
